import math
import unittest

from solution import bracketed_zero, evaluate_series


class SeriesEvaluationTests(unittest.TestCase):
    def test_coefficients_are_in_ascending_power_order(self):
        coefficients = [2, 3, 4]
        self.assertEqual(evaluate_series(coefficients, 2), 24.0)
        self.assertEqual(evaluate_series([5], -100), 5.0)

    def test_evaluation_does_not_mutate_coefficients(self):
        coefficients = [1, -2, 3]
        before = list(coefficients)
        evaluate_series(coefficients, 2)
        self.assertEqual(coefficients, before)

    def test_evaluation_validation(self):
        with self.assertRaises(TypeError):
            evaluate_series((1, 2), 1)
        with self.assertRaises(ValueError):
            evaluate_series([], 1)
        for coefficients in ([True], ["1"], [complex(1, 0)]):
            with self.subTest(coefficients=coefficients), self.assertRaises(TypeError):
                evaluate_series(coefficients, 1)
        for coefficients in ([float("nan")], [float("inf")]):
            with self.subTest(coefficients=coefficients), self.assertRaises(ValueError):
                evaluate_series(coefficients, 1)
        for point in (True, "1", complex(1, 0)):
            with self.subTest(point=point), self.assertRaises(TypeError):
                evaluate_series([1], point)
        for point in (float("nan"), float("inf"), float("-inf")):
            with self.subTest(point=point), self.assertRaises(ValueError):
                evaluate_series([1], point)


class BracketedZeroTests(unittest.TestCase):
    def test_endpoint_roots_are_returned_as_floats(self):
        left = bracketed_zero([0, 1], 0, 5)
        right = bracketed_zero([-5, 1], 0, 5)
        self.assertEqual(left, 0.0)
        self.assertEqual(right, 5.0)
        self.assertIsInstance(left, float)
        self.assertIsInstance(right, float)

    def test_bisection_chooses_the_bracketing_half(self):
        root = bracketed_zero([-2, 0, 1], 0, 2, tolerance=1e-10)
        self.assertAlmostEqual(root, math.sqrt(2), delta=1e-10)
        self.assertGreater(root, 1.0)
        self.assertLess(root, 2.0)

    def test_exact_midpoint_root(self):
        self.assertEqual(bracketed_zero([-3, 1], 0, 6), 3.0)

    def test_stops_immediately_when_width_is_at_most_tolerance(self):
        self.assertEqual(bracketed_zero([-0.25, 1], 0, 1, tolerance=1), 0.5)
        self.assertEqual(bracketed_zero([-0.25, 1], 0, 1, tolerance=2), 0.5)

    def test_constant_polynomials(self):
        self.assertEqual(bracketed_zero([0], -2, 4), -2.0)
        with self.assertRaises(ValueError):
            bracketed_zero([3], -2, 4)

    def test_rejects_interval_without_sign_change(self):
        with self.assertRaises(ValueError):
            bracketed_zero([1, 0, 1], -2, 2)
        with self.assertRaises(ValueError):
            bracketed_zero([-2, 0, 1], 2, 3)

    def test_interval_and_tolerance_validation(self):
        for left, right in ((1, 1), (2, 1)):
            with self.subTest(left=left, right=right), self.assertRaises(ValueError):
                bracketed_zero([-1, 1], left, right)
        for tolerance in (0, -1, float("nan"), float("inf")):
            with self.subTest(tolerance=tolerance), self.assertRaises(ValueError):
                bracketed_zero([-1, 1], 0, 2, tolerance)
        for name, value in (("left", True), ("right", "2"), ("tolerance", None)):
            with self.subTest(name=name, value=value), self.assertRaises(TypeError):
                if name == "left":
                    bracketed_zero([-1, 1], value, 2)
                elif name == "right":
                    bracketed_zero([-1, 1], 0, value)
                else:
                    bracketed_zero([-1, 1], 0, 2, value)
        for left, right in ((float("nan"), 2), (0, float("inf"))):
            with self.subTest(left=left, right=right), self.assertRaises(ValueError):
                bracketed_zero([-1, 1], left, right)

    def test_coefficients_are_not_mutated(self):
        coefficients = [-2, 0, 1]
        before = list(coefficients)
        bracketed_zero(coefficients, 0, 2, 1e-6)
        self.assertEqual(coefficients, before)


if __name__ == "__main__":
    unittest.main()

